        .{ .path = "Terminal.switchScreen", .returns = .borrowed },
        .{ .path = "Terminal.switchScreenMode" },
        .{ .path = "root.activeScreen", .returns = .borrowed },
        .{ .path = "root.screen", .returns = .borrowed },
